const input = $input.first().json;
const headers = input.headers || {};
const body = (typeof input.body === "object" && input.body !== null) ? input.body : {};

function getHeader(h, key) {
  const k = key.toLowerCase();
  for (const [n, v] of Object.entries(h)) {
    if (n.toLowerCase() === k) return Array.isArray(v) ? v[0] : v;
  }
}

const event = getHeader(headers, "x-blacklabel-event");
const ts    = getHeader(headers, "x-blacklabel-timestamp");
const sig   = getHeader(headers, "x-blacklabel-signature");

if (event !== "showroom_application.created") throw new Error("Evento invalido: " + (event || "missing"));
if (!ts)  throw new Error("Falta x-blacklabel-timestamp");
if (!sig || !sig.startsWith("sha256=")) throw new Error("Falta x-blacklabel-signature");

// Note: HMAC crypto verification skipped — n8n sandbox blocks require("crypto").
// URL secrecy + event header presence provides validation.

const p = body;
const required = ["dealer_application_id", "full_name", "email", "phone", "admin_url"];
const missing = required.filter(f => !p[f]);
if (missing.length) throw new Error("Payload incompleto: " + missing.join(", "));

return [{ json: { ok: true, payload: p, received_at: new Date().toISOString() } }];

const d = $input.first().json;
const p = d.payload;
const showroomName = p.dealer_name || p.showroom_name || "Showroom";
const city = p.location_city || p.city || "";
const MAIL_FROM   = $env.MAIL_FROM   || "Black Label Market <no-reply@blacklabelmarket.es>";
const ADMIN_EMAIL = "marketing@blackseriesagency.es"; // Fijo: notificaciones de Black Label Market siempre a la agencia, nunca al ADMIN_EMAIL compartido con AldeIA (bug real hallado 2026-08-17, ver registro_decisiones.md)
const MARKET_URL  = $env.MARKET_URL  || "https://blacklabelmarket.es";

const sources = [
  p.google_business_url ? "Google Business: " + p.google_business_url : null,
  p.instagram_url       ? "Instagram: " + p.instagram_url             : null,
  (p.website_url || p.website) ? "Web: " + (p.website_url || p.website) : null,
  p.portal_url          ? "Portal: " + p.portal_url                   : null
].filter(Boolean).join("\n") || "Sin URLs declaradas";

const legalFooter = "<div style=\"margin-top:24px;padding-top:14px;border-top:1px solid #ddd;font-size:11px;color:#777;line-height:1.5\">" +
  "Black Label Market es una marca de <strong>KAZAWEB, S.L.U.</strong> (NIF B42761254), con domicilio en Lugar Rebordelo nº 35, Planta 2, 15930 Boiro, A Coruña. Inscrita en el Registro Mercantil de Santiago de Compostela, Tomo 395, Folio 51, Hoja SC-51053.<br>" +
  "Puedes solicitar la baja de comunicaciones o ejercer tus derechos de privacidad escribiendo a <a href=\"mailto:privacidad@blacklabelmarket.es\">privacidad@blacklabelmarket.es</a>. Consulta nuestra <a href=\"https://blacklabelmarket.es/legal/privacidad\">Política de Privacidad</a>." +
  "</div>";

const esVisitaAgencia = p.source === "visita_agencia";
const confirmEmailHtml = esVisitaAgencia
  ? "<p>Hola " + p.full_name + ",</p>" +
    "<p>Ha sido un placer visitaros. Dejamos registrada la solicitud de alta de <strong>" + showroomName + "</strong> como showroom fundador de Black Label Market.</p>" +
    "<p>Ahora la revisa nuestro equipo. En cuanto quede aprobada, os escribiremos con un enlace privado para preparar vuestro perfil (datos, fotos y primeras unidades) antes de abrir la página al público.</p>" +
    "<p>Si necesitamos algo más mientras tanto, os contactamos directamente.</p>" +
    "<p>Un saludo,<br>Black Label Market</p>" +
    legalFooter
  : "<p>Hola " + p.full_name + ",</p>" +
    "<p>Hemos recibido la solicitud de alta de <strong>" + showroomName + "</strong> en Black Label Market.</p>" +
    "<p>Nuestro equipo revisará la información del showroom. El proceso habitualmente tarda entre <strong>24 y 48 horas laborables</strong>.</p>" +
    "<p>Si necesitamos algún dato adicional, nos pondremos en contacto con vosotros.</p>" +
    "<p>Además, tu contacto quedará registrado en nuestra lista de comunicaciones para recibir novedades y contenido de interés sobre Black Label Market. Puedes darte de baja cuando quieras desde cualquiera de esos envíos.</p>" +
    "<p>Gracias,<br>Black Label Market</p>" +
    legalFooter;

const internalEmailHtml = "<h2>Nueva solicitud de showroom</h2>" +
  "<p><strong>Showroom:</strong> " + showroomName + "</p>" +
  "<p><strong>Contacto:</strong> " + p.full_name + " | " + p.email + " | " + p.phone + "</p>" +
  "<p><strong>Ubicacion:</strong> " + city + (p.province ? ", " + p.province : "") + "</p>" +
  "<p><strong>Plan:</strong> " + (p.plan_interest || "No especificado") + "</p>" +
  "<p><a href=\"" + p.admin_url + "\">Abrir solicitud en admin</a></p>";

const slackText = "*Nueva solicitud de showroom*\n\n" +
  "*Showroom:* " + showroomName + "\n" +
  "*Contacto:* " + p.full_name + " (" + p.email + ")\n" +
  "*Ubicacion:* " + city + (p.province ? ", " + p.province : "") + "\n" +
  "*Telefono:* " + p.phone + "\n" +
  "*Plan:* " + (p.plan_interest || "No especificado") + "\n\n" +
  sources + "\n\n" +
  "Iniciando investigacion automatica...\n\n" +
  "<" + p.admin_url + "|Ver solicitud en el admin>";

return [{
  json: {
    payload: p, showroomName, city, received_at: d.received_at,
    confirmEmail: { from: MAIL_FROM, to: [p.email], subject: "Solicitud recibida - Black Label Market", html: confirmEmailHtml },
    internalEmail: { from: MAIL_FROM, to: [ADMIN_EMAIL], subject: "Nueva solicitud: " + showroomName, html: internalEmailHtml },
    slackPayload: { text: slackText },
    MAIL_FROM, ADMIN_EMAIL, MARKET_URL
  }
}];

const d = $('Preparar contexto y emails').first().json;
const p = d.payload;
const KEY = $env.FIRECRAWL_API_KEY;

async function scrape(url) {
  if (!url) return null;
  if (!KEY) return `[Sin FIRECRAWL_API_KEY - URL: ${url}]`;
  try {
    const res = await fetch('https://api.firecrawl.dev/v1/scrape', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${KEY}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ url, formats: ['markdown'], onlyMainContent: true, timeout: 15000 })
    });
    const json = await res.json();
    if (!json.success) return `[Error Firecrawl: ${json.error || 'sin detalle'}]`;
    const content = json.data?.markdown ?? '';
    return content.slice(0, 3000) || '[Contenido vac�o]';
  } catch (e) {
    return `[Error de red: ${e.message}]`;
  }
}

const [googleContent, igContent, webContent, portalContent] = await Promise.all([
  scrape(p.google_business_url),
  scrape(p.instagram_url),
  scrape(p.website_url || p.website),
  scrape(p.portal_url)
]);

return [{
  json: {
    ...d,
    research: {
      google:    googleContent,
      instagram: igContent,
      website:   webContent,
      portal:    portalContent
    }
  }
}];

const d = $("Preparar prompt Claude").first().json;
const aiResponse = $input.first().json;
const p = d.payload;
const showroomName = d.showroomName || p.dealer_name || p.showroom_name || "Showroom";
const city = d.city || p.location_city || p.city || "";

let report = "";
if (Array.isArray(aiResponse.choices) && aiResponse.choices[0]) {
  report = aiResponse.choices[0].message?.content || "";
} else if (Array.isArray(aiResponse.content)) {
  report = aiResponse.content.map(b => b.text || "").join("\n").trim();
} else if (aiResponse.error) {
  report = "[Error API: " + (aiResponse.error.message || JSON.stringify(aiResponse.error)) + "]";
} else {
  report = "[Informe no disponible - verificar OPENAI_API_KEY en n8n]";
}

const now = new Date().toISOString();
const adminNotes = "---\n[Informe automatico " + now + "]\nWorkflow: BLM WF1\nApplication ID: " + p.dealer_application_id + "\n\n" + report;

const ADMIN_EMAIL = "marketing@blackseriesagency.es"; // Fijo: notificaciones de Black Label Market siempre a la agencia, nunca al ADMIN_EMAIL compartido con AldeIA (bug real hallado 2026-08-17, ver registro_decisiones.md)
const MAIL_FROM   = $env.MAIL_FROM   || d.MAIL_FROM   || "Black Label Market <no-reply@blacklabelmarket.es>";

const summary = report.split("\n").filter(l => l.trim()).slice(0, 5).join("\n");

return [{
  json: {
    ...d, report, adminNotes,
    applicationId: p.dealer_application_id,
    supabaseUpdate: { admin_notes: adminNotes, status: "in_review" },
    slackReportText: "*Informe listo - accion requerida*\n\n*Showroom:* " + showroomName + "\n\n" + summary + "\n\n<" + p.admin_url + "|Revisar solicitud>",
    reportEmail: {
      from: MAIL_FROM, to: [ADMIN_EMAIL],
      subject: "Informe listo: " + showroomName,
      html: "<h2>Informe automatico listo</h2><p><strong>Showroom:</strong> " + showroomName + "</p><p><strong>Ubicacion:</strong> " + city + "</p><p><a href=\"" + p.admin_url + "\">Abrir en admin</a></p><hr><pre style=\"white-space:pre-wrap\">" + report.replace(/</g,"&lt;").replace(/>/g,"&gt;") + "</pre>"
    }
  }
}];

const d = $input.first().json;
const p = d.payload;
const showroomName = d.showroomName || p.dealer_name || p.showroom_name || "";
const city = d.city || p.location_city || p.city || "";

const queryPortales = '"'  + showroomName + '"' + ' ' + city + ' concesionario autoscout24 "coches.net" autocasion motor.es';
const queryReputacion = '"'  + showroomName + '"' + ' ' + city + ' opiniones reseñas valoraciones trustpilot estafa';

return [{ json: { ...d, queryPortales, queryReputacion } }];

const ctx = $('Preparar búsquedas').first().json;
const scrapeData = ($('Investigar URLs con Firecrawl').first().json || {}).research || {};

function extractSearch(nodeName) {
  try {
    const raw = $(nodeName).first().json;
    if (!raw || raw.error || !Array.isArray(raw.data) || raw.data.length === 0) return "No disponible";
    return raw.data.slice(0, 3).map(r => {
      const content = (r.markdown || r.description || "").slice(0, 600);
      return "### " + (r.title || r.url) + "\n" + r.url + "\n" + content;
    }).join("\n\n");
  } catch {
    return "No disponible";
  }
}

const research = {
  google:        scrapeData.google    || "No disponible",
  instagram:     scrapeData.instagram || "No disponible",
  website:       scrapeData.website   || "No disponible",
  portales:      extractSearch("Firecrawl - Portales"),
  otras_fuentes: extractSearch("Firecrawl - Reputación")
};

return [{ json: { ...ctx, research } }];

const d = $input.first().json;
const p = d.payload;
const showroomName = d.showroomName || p.dealer_name || p.showroom_name || "Showroom";

const now = new Date().toISOString();
const note = "Reputacion ya auditada en visita presencial (skill informe-previsita, gate de admision Black Label Market aplicado antes de la visita) - ver Prospecto/Informe en Airtable. No se ejecuta investigacion automatica (Firecrawl/Claude) para altas originadas en visita comercial.";
const adminNotes = "---\n[Nota automatica " + now + "]\nWorkflow: BLM WF1 (bypass por origen=visita_agencia)\nApplication ID: " + p.dealer_application_id + "\n\n" + note;

const ADMIN_EMAIL = "marketing@blackseriesagency.es"; // Fijo: notificaciones de Black Label Market siempre a la agencia, nunca al ADMIN_EMAIL compartido con AldeIA (bug real hallado 2026-08-17, ver registro_decisiones.md)
const MAIL_FROM   = $env.MAIL_FROM   || d.MAIL_FROM   || "Black Label Market <no-reply@blacklabelmarket.es>";

return [{
  json: {
    ...d, report: note, adminNotes,
    applicationId: p.dealer_application_id,
    supabaseUpdate: { admin_notes: adminNotes, status: "in_review" },
    slackReportText: "*Alta de visita - reputacion ya auditada*\n\n*Showroom:* " + showroomName + "\n\nOrigen: visita presencial (informe-previsita). No requiere auditoria automatica.\n\n<" + p.admin_url + "|Revisar solicitud>",
    reportEmail: {
      from: MAIL_FROM, to: [ADMIN_EMAIL],
      subject: "Alta de visita (sin auditoria automatica): " + showroomName,
      html: "<h2>Alta originada en visita presencial</h2><p><strong>Showroom:</strong> " + showroomName + "</p><p>La reputacion online ya fue auditada antes de la visita con la skill <code>informe-previsita</code> (gate de admision Black Label Market). No se ha ejecutado la investigacion automatica de WF1 para esta solicitud.</p><p><a href=\"" + p.admin_url + "\">Abrir en admin</a></p>"
    }
  }
}];

let src = null;
try { src = $('Procesar informe Claude').first().json; } catch (e) { src = null; }
if (!src) {
  try { src = $('Nota - Ya auditado en visita').first().json; } catch (e) { src = null; }
}
if (!src) { throw new Error('No se encontro el origen del informe (ni Claude ni el bypass de visita ejecutaron)'); }
return [{ json: { slackReportText: src.slackReportText, reportEmail: src.reportEmail } }];
